  ('002030a9-c515-4c1e-ba08-6508cd060f04', 'fotostudio-farbtonwerk-phot', 'Fotostudio Farbtonwerk', 'photography', 'berlin-berlin', 'Wir sind ein Team aus Fotografin und Fotograf in Berlin Mitte und sind spezialisiert auf niveauvolle Fotografie, egal ob Akt, Babybauch oder auch authetische Business, Bewerbungsfotos und Datingfotos.', '', '', '+493055140516', false, 'active', '{"source": "allefotografen.de", "source_url": "https://www.allefotografen.de/fotostudio-farbtonwerk", "specializations": ["hochzeit", "portrait", "business", "baby", "familie", "mode", "architektur"]}'::jsonb),
