  ('2f937b84-8568-4669-895e-396b35faf59e', 'philipp-eigner-media-production-phot', 'Philipp Eigner Media Production', 'photography', 'hamburg-hamburg', 'Ich bin Fotograf und Videograf für die zwei Bereiche Industrie/Business und Architektur. Als ehemaliger Maschinenbauingenieur und Fotograf, der schon sein ganzes Leben lang der Fotografie und dem Design verbunden ist, stehe ich für künstlerisch ansprechende Arbeiten, die zugleich in einem stringenten Prozess für Sie und mit Ihnen erarbeitet werden.', '', '', '+4917697832742', false, 'active', '{"source": "allefotografen.de", "source_url": "https://www.allefotografen.de/philipp-eigner-media-production", "specializations": ["portrait", "business", "architektur"]}'::jsonb),
