  ('2a5e04e8-0ebb-4019-908d-ab38022156a7', 'photonenhexe-phot', 'Photonenhexe', 'photography', 'hamburg-hamburg', 'Photonenhexe: Wo das Handwerk Kunst küsst! Die Photonenhexe ist deine Fotografin in Bremen wenn es um Portraits der Extraklasse geht. Denn du bist Individuell und verdienst individuelle Fotos! Schluss mit den immer gleichen Looks! Wir planen alles so wie du es brauchst. Denn deine Fotos sollen dich empowern und weiter im Leben bringen. Ein Gang zur Fotografin sollte sich nicht wie ein Zahnarztbesu', '', '', '017695709980', false, 'active', '{"source": "allefotografen.de", "source_url": "https://www.allefotografen.de/photonenhexe", "specializations": ["hochzeit", "portrait", "baby", "familie", "architektur"]}'::jsonb),
  ('a9e4d27e-cedb-4655-8069-323d0c01273d', 'phowoto-phot', 'Phowoto', 'photography', 'hamburg-hamburg', 'Mein Name ist Wolfgang Weber. I fotografiere aus Leidenschaft schon seit vielen Jahren. In der Zwischenzeit habe ich mich in den professionellen Bereich bewegt und möchte diesen auch weiter ausbauen.', '', '', '', false, 'active', '{"source": "allefotografen.de", "source_url": "https://www.allefotografen.de/phowoto-2", "specializations": ["hochzeit", "portrait", "event", "mode", "food", "architektur", "produkt", "sport"]}'::jsonb),
  ('d600024d-e4e8-40c7-9576-94ab04f49515', 'picselweb-phot', 'Picselweb', 'photography', 'hamburg-hamburg', 'Dein Sportfotograf für Sportevents und Teamshootings
