  ('87cf8eca-38ca-44e3-bbb7-6436538f8886', 'bruno-kapeller-phot', 'Bruno Kapeller', 'photography', 'muenchen-muenchen', 'Dann sende mir gern eine Nachricht über das Kontaktformular!', '', '', '0049 1732530863', false, 'active', '{"source": "allefotografen.de", "source_url": "https://www.allefotografen.de/bruno-kapeller", "specializations": ["event", "familie", "architektur", "produkt", "sport"]}'::jsonb),
  ('9cb40d47-7f20-4693-8c4c-66e843abca87', 'bse-pictures-de-phot', 'BSE-Pictures.de', 'photography', 'muenchen-muenchen', 'Die Medienagentur BSE Pictures ist spezialisiert in den Bereichen Fotografie, Videoproduktion und Website. Wir erstellen Fotoproduktionen, Videoproduktionen und Webseiten für Unternehmen. Unsere Auftraggeber kommen aus dem Bereichen Hotel, Industrie, TV-Produktionen, Kinoproduktionen sowie E-Commerce.', '', '', '08861 900459', false, 'active', '{"source": "allefotografen.de", "source_url": "https://www.allefotografen.de/bse-pictures-de", "specializations": ["food", "architektur", "produkt", "sport"]}'::jsonb),
  ('74e41c98-a5c6-4523-895b-79c61b801cf1', 'markus-bauer-fotografie-phot', 'Markus Bauer - Fotografie', 'photography', 'muenchen-muenchen', 'Wenn da Markus Buidl baut // Hochzeit, Portrait, Pärchen, Beauty // Erding, Bayern 

