  ('7ffdbb85-abdf-499b-8866-6d916f9e49f5', 'chetan-kapoor-photography-phot', 'Chetan Kapoor Photography', 'photography', 'muenchen-muenchen', 'My company specializes in photography and videography services with a focus on storytelling, natural visuals, and modern editing. Based in Munich, we work with individuals, brands, and businesses to create authentic content — from personal portraits and events to corporate videos and social media clips. We aim to keep the process simple, creative, and client-focused.', '', '', '017643183377', false, 'active', '{"source": "allefotografen.de", "source_url": "https://www.allefotografen.de/chetan-kapoor-photography", "specializations": ["hochzeit", "portrait", "business", "event", "baby", "familie", "mode", "food", "architektur", "produkt", "sport"]}'::jsonb),
