  ('15ffa4bf-1aca-4e20-b87f-b1aa895bd42d', 'chris-frumolt-phot', 'Chris Frumolt', 'photography', 'muenchen-muenchen', 'Schön dass Du hier bei mir vorbeschaust :-)

