  ('67e906d2-31a0-4da9-8bca-344bf56c0752', 'familienfotografin-emorah-phot', 'Familienfotografin EMORAH', 'photography', 'muenchen-muenchen', 'Ich bin Sarah, 29 Jahre alt und stecke mein ganzes Herzblut in authentische Familien- und Kinderfotos. Wenn ich mal nicht am Fotos schießen oder Bearbeiten bin, mache ich viel Sport oder bin in den Bergen unterwegs beim Wandern oder Skifahren.', '', '', '+4915775880972', false, 'active', '{"source": "allefotografen.de", "source_url": "https://www.allefotografen.de/familienfotografin-emorah", "specializations": ["portrait", "baby", "familie", "mode", "sport"]}'::jsonb),
  ('4d743ded-5c29-493b-a653-cf178af1041d', 'fichtner-fotodesign-phot', 'Fichtner Fotodesign', 'photography', 'muenchen-muenchen', 'Ihr kreativer Partner für Fotografie im Münchner Osten und weit darüber hinaus. EVENTFOTOGRAFIE, WERBEFOTOGRAFIE und PRODUKTFOTOGRAFIE bilden die Schwerpunkte meiner Leistungen, meine Leidenschaft für die Fotografie endet damit aber nicht und so kann ich Ihnen in vielfältiger Weise bei Ihren Vorhaben als Fotograf und Fotodesigner zur Seite stehen. Die Themenwelten in der Fotografie und in Ihrer Ve', '', '', '+49 1601831433', false, 'active', '{"source": "allefotografen.de", "source_url": "https://www.allefotografen.de/fichtner-fotodesign", "specializations": ["event", "familie", "architektur", "produkt", "sport"]}'::jsonb),
  ('7c3bf0de-8b36-4488-b364-8348f5cbe567', 'fifomata-de-phot', 'fifomata.de', 'photography', 'muenchen-muenchen', 'Wir freuen uns über Euren Besuch ✌️👍.
