  ('d27e6209-6133-48aa-8101-29adec7baf5a', 'fotografie-rohde-phot', 'Fotografie Rohde', 'photography', 'koeln-koeln', 'Dann sende mir gern eine Nachricht über das Kontaktformular!', '', '', '', false, 'active', '{"source": "allefotografen.de", "source_url": "https://www.allefotografen.de/fotografie-rohde", "specializations": ["hochzeit", "portrait", "baby", "mode", "food", "architektur", "produkt", "sport"]}'::jsonb),
  ('27bcf9fe-cffa-4dbb-89a0-892fbbb98bb8', 'fotografin-aachen-phot', 'fotografin-aachen', 'photography', 'koeln-koeln', 'Menschen zu fotografieren ist meine große Leidenschaft. Ich quetsche euch nicht in eine bestimmtes Format, sondern gebe euch genügend Raum geben, um euch authentische Bilder zeigen zu können. Im der Portraitotografie bin ich eine Allrounderin.', '', '', '0241 46825058', false, 'active', '{"source": "allefotografen.de", "source_url": "https://www.allefotografen.de/fotografin-aachen", "specializations": ["hochzeit", "portrait", "business", "baby", "familie", "sport"]}'::jsonb),
  ('0c360562-c844-42c1-9268-06167063ff98', 'fotojuwelier-phot', 'fotojuwelier', 'photography', 'koeln-koeln', 'Wir sind Kristina & Timo.

