  ('32c3f460-14e6-4fa2-8b25-89e647b938c8', 'stefanie-s-tierfotografie-phot', 'Stefanie''s Tierfotografie', 'photography', 'koeln-koeln', 'Ich bin Stefanie und liebe die Tierfotografie. Es gibt für mich nichts schöneres als , dieses freudige Gefühl nach einem Shooting, endlich die Bilder durchzusehen.', '', '', '+491774411021', false, 'active', '{"source": "allefotografen.de", "source_url": "https://www.allefotografen.de/stefanie-s-tierfotografie", "specializations": ["hochzeit", "portrait", "newborn", "baby", "familie", "mode"]}'::jsonb),
  ('caa53e44-3486-4b61-9d60-43a12817482d', 'steffi-atze-phot', 'Steffi Atze', 'photography', 'koeln-koeln', 'Seit über 30 Jahren fotografiere ich Menschen mit Charakter und Haltung – vom Geschäftsführer bis zum Autor, vom Arzt bis zum Richter.
