  ('1554c67d-2101-416a-b1b2-ae505d469ff3', 'uwe-schinkel-phot', 'Uwe Schinkel', 'photography', 'koeln-koeln', '"Realistisch, authentisch und glaubwürdig sind die Schlagworte, die den Markt für Werbebilder dominieren.“ schrieb Jaqueline Bourke von Getty Images über die Zukunft des Bildermarktes im Nikon Magazin (2019). Für meinen Geschmack fehlt in der Aufzählung der Bergriff: divers. Genau diese Wörter sind für mich gute Gefährte auf dem Weg zu guten Bildern. Insofern hat sie mir sehr aus dem Herzen gespro', '', '', '+491772478361', false, 'active', '{"source": "allefotografen.de", "source_url": "https://www.allefotografen.de/uwe-schinkel", "specializations": ["hochzeit", "portrait", "event", "produkt"]}'::jsonb),
  ('b1ca4316-20da-4ef0-a292-a3e0ca462f72', 'vanessa-s-lichtmomente-phot', 'Vanessa''s Lichtmomente', 'photography', 'koeln-koeln', 'Herzlich Willkommen!
