  ('f48a83b9-a6bf-44e8-943c-21bf98dba448', 'abcwedding-phot', 'abcwedding', 'photography', 'frankfurt-frankfurt', 'Kein Bock auf gezwungene und künstliche Hochzeitsfotos? Ich begleite Euch für natürliche und echte Aufnahmen - entspannt und locker!', '', '', '015224665211', false, 'active', '{"source": "allefotografen.de", "source_url": "https://www.allefotografen.de/abcwedding", "specializations": ["hochzeit", "portrait", "event", "newborn", "familie"]}'::jsonb),
