  ('c10ca7f1-7096-49f7-9809-4eee64716003', 'veronica-dinges-fotografie-phot', 'Veronica Dinges Fotografie', 'photography', 'frankfurt-frankfurt', 'Mein Ziel ist es, dich glücklich zu machen. Dich so zu fotografieren, dass du dir gefällst. Es soll nicht einfach nur ein Foto werden. Es geht um die Persönlichkeit jedes einzelnen, um Emotionen, Verbindungen und die Kunst, die Schönheit des Augenblicks einzufangen. Jeder hat seine eigene Geschichte zu erzählen.', '', '', '017641874782', false, 'active', '{"source": "allefotografen.de", "source_url": "https://www.allefotografen.de/veronica-dinges-fotografie", "specializations": ["hochzeit", "portrait", "baby", "familie", "mode", "food", "architektur", "sport"]}'::jsonb),
