  ('6d8ee5f5-0445-436b-843e-a19054b81280', 'amazoid-produktfotografie-phot', 'Amazoid - Produktfotografie', 'photography', 'stuttgart-stuttgart', 'Dann sende mir gern eine Nachricht über das Kontaktformular!', '', '', '', false, 'active', '{"source": "allefotografen.de", "source_url": "https://www.allefotografen.de/amazoid-produktfotografie", "specializations": ["hochzeit", "portrait", "baby", "familie", "mode", "food", "architektur", "produkt", "sport"]}'::jsonb),
