  ('274236e6-0638-46c8-92de-8807e0e3cc81', 'hermann-foto-design-phot', 'Hermann Foto & Design', 'photography', 'stuttgart-stuttgart', 'Profifotograf mit solider Handwerksausbildung mit eigenem Fotostudio seit 1985. Bis 2022. Ab 2022 Produktionen on location oder in Mietstudios mit umfangreicher mobiler Ausrüstung.', '', '', '+497116365685', false, 'active', '{"source": "allefotografen.de", "source_url": "https://www.allefotografen.de/hermann-foto-design", "specializations": ["hochzeit", "portrait", "architektur", "produkt", "sport"]}'::jsonb),
  ('e8e1f995-a212-4cf7-b827-11ba472f9a16', 'herzblut-studio-phot', 'Herzblut Studio', 'photography', 'stuttgart-stuttgart', 'Wir kommen aus unterschiedlichsten Foto- 
