  ('86727c93-70c6-49ff-837e-e61cb620b763', 'hs-foto-phot', 'HS-FOTO', 'photography', 'stuttgart-stuttgart', 'Seit ca. 10 Jahren bin ich immer wieder hauptsächlich im Schwarzwald unterwegs, um die Landschaft bei unterschiedlichen Wetter- und Lichtverhältnissen "in Szene zu setzen", Neben Landschaftsfotos mache ich auch gerne Konzert- oder Architekturfotos.', '', '', '015229249848', false, 'active', '{"source": "allefotografen.de", "source_url": "https://www.allefotografen.de/hs-foto", "specializations": ["hochzeit", "portrait", "event", "familie", "architektur", "produkt", "sport"]}'::jsonb),
  ('99284074-ccb6-477b-b874-0dbad6a54631', 'imagephoto-phot', 'IMAGEPHOTO', 'photography', 'stuttgart-stuttgart', 'Ich bin ein alter Hase und seit 40 Jahren im Bereich Fotografie unterwegs. 
