  ('c6479f2e-29a5-4a6c-a169-3a407e1daef2', 'inna-ibach-phot', 'Inna Ibach', 'photography', 'stuttgart-stuttgart', 'Outdoor Fotografie in Herbrechtingen. Familien- und Kinderfotografie.', '', '', '01701821271', false, 'active', '{"source": "allefotografen.de", "source_url": "https://www.allefotografen.de/inna-ibach", "specializations": ["portrait", "baby", "familie", "mode", "produkt"]}'::jsonb),
  ('822a7e0b-f490-4e18-aa6a-577b7cb56a99', 'irina-miller-fotografie-phot', 'Irina Miller Fotografie', 'photography', 'stuttgart-stuttgart', 'Ich bin Irina Miller, erfahrene Baby- und Familienfotograf für Rottweil, Villingen-Schwenningen, Umgebung und die Schwarzwald-Region. In meinem großzügigen, liebevoll eingerichteten Fotostudio entstehen natürliche, zeitlose und emotionale Baby-, Newborn-, Babybauch-, Kinder-, Paar- und Familienfotos sowie kreative Cake Smash Shootings. Auch Hochzeiten begleite ich mit viel Herz und voller Aufmerks', '', '', '+4917632222784', false, 'active', '{"source": "allefotografen.de", "source_url": "https://www.allefotografen.de/irina-miller-fotografie", "specializations": ["hochzeit", "portrait", "newborn", "baby", "familie"]}'::jsonb),
  ('3be88bd4-5301-421b-96dc-60cccad3a9cf', 'irina-wonneberg-tierfotografie-phot', 'Irina Wonneberg Tierfotografie', 'photography', 'stuttgart-stuttgart', 'Ich bin professionelle Tierfotografin aus Kirchheim Teck mit Schwerpunkt Hunde- und Pferdefotografie. Mein Einsatzgebiet erstreckt sich mittlerweile auf ganz Süddeutschland. Bei meinen Kundinnen und Kunden ist die Reihe "Seelenmomente" besonders beliebt. Sie zeigt sanfte und sehr nahe Augenblicke zwischen zwei Tieren sowie auch zwischen den Tieren und ihren Menschen. In einem kostenlosen Informati', '', '', '+49 176 21187 267', false, 'active', '{"source": "allefotografen.de", "source_url": "https://www.allefotografen.de/irina-wonneberg-tierfotografie", "specializations": ["hochzeit", "familie", "architektur", "sport"]}'::jsonb),
