  ('183750a7-a198-4218-af8a-705043e13bcb', 'paul-schneider-phot', 'Paul Schneider', 'photography', 'duesseldorf-duesseldorf', 'Dann sende mir gern eine Nachricht über das Kontaktformular!', '', '', '017622601339', false, 'active', '{"source": "allefotografen.de", "source_url": "https://www.allefotografen.de/paul-schneider", "specializations": ["hochzeit", "portrait", "familie", "produkt", "sport"]}'::jsonb),
  ('175c43d4-af89-4b02-af83-78085f396003', 'pfotenfaktor-phot', 'Pfotenfaktor', 'photography', 'duesseldorf-duesseldorf', 'Dein Fotoshooting
Es ist dein besonderes Erlebnis!
